-- All Swedish postal codes (postnummer), sourced from GeoNames
-- (download.geonames.org/export/zip/SE.zip, CC BY 4.0), 18887 entries as
-- of 2026-09. One row per postnummer with its place name, län, and
-- approximate coordinates (locality-level, not exact address points).
-- A static reference table - not written to by any adapter - useful for
-- geocoding, search, or grouping outages by postal-code area.

CREATE TABLE postnummer (
    postal_code TEXT PRIMARY KEY,
    place TEXT NOT NULL,
    lan TEXT NOT NULL,
    lat DOUBLE PRECISION NOT NULL,
    lng DOUBLE PRECISION NOT NULL
);

CREATE INDEX idx_postnummer_place ON postnummer (place);
CREATE INDEX idx_postnummer_lan ON postnummer (lan);

